<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><link rel="stylesheet" href="../style.css"><title>Scan Attendance QR</title></head>
<body><main><div class="course-qr"><div class="course-title-qr">Introduction to Computing</div><div class="time-title"><span id="time">Loading...</span> <span id="date">Loading...</span></div></div><div class="main-qr-container"><p class="qr-info">Scan the QR code with your device while logged in with your ID.</p><div class="qr-scan"><img src="../assets/logo.png" alt="QR code placeholder"></div><div class="qr-reset-time">Code resets in <span>15</span> seconds</div></div><div class="qr-updates"><p class="qr-update-txt">Updates:</p><div class="qr-update-table"><div class="qr-update-head"><div class="id">ID</div><div class="time">Time</div><div class="status">Status</div></div><div class="no-scan-msg">No one has scanned yet.</div></div></div></main><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script>const qrContainer=document.querySelector('.qr-scan');let seconds=15;function refreshQr(){qrContainer.innerHTML='';new QRCode(qrContainer,{text:'CS101-DEMO',width:150,height:150});seconds=15;}refreshQr();setInterval(function(){document.querySelector('.qr-reset-time span').textContent=seconds--;if(seconds<0)refreshQr();},1000);</script><script src="../script.js"></script></body></html>
